'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useRouter } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { queryKeys } from '@/lib/query-keys'
import { formatCurrency } from '@/lib/utils'
import { toast } from 'sonner'
import { CheckCircle2, AlertCircle, Settings } from 'lucide-react'
import { BulkThresholdsDrawer } from '@/components/inventory/BulkThresholdsDrawer'
import { CATEGORY_MIN_DEFAULTS_LABEL } from '@/lib/inventory/category-defaults'

// ── Types ────────────────────────────────────────────────────────────────────

interface StockAlertItem {
  id: string
  item_id: string
  alert_type: string
  current_stock: number
  threshold: number
  // joined item fields from extended GET response
  name: string
  sku: string | null
  min_threshold: number
  cost_per_unit_cents: number | null
  supplier_id: string | null
  supplier_name: string | null
  suggested_qty: number
}

interface StockAlertsResponse {
  alerts: StockAlertItem[]
  state: 'all_clear' | 'cant_fire' | 'has_alerts'
  items_with_no_min: number
  total: number
}

// ── Main component ────────────────────────────────────────────────────────────

export function StockAlertsPanel() {
  const queryClient = useQueryClient()
  const router = useRouter()

  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [thresholdsOpen, setThresholdsOpen] = useState(false)
  const [thresholdsMode, setThresholdsMode] = useState<'manual' | 'review-only'>('manual')
  const [useDefaultsDialogOpen, setUseDefaultsDialogOpen] = useState(false)

  const { data, isLoading } = useQuery({
    queryKey: queryKeys.inventory.stockAlerts(),
    queryFn: async () => {
      const res = await fetch('/api/inventory/stock-alerts')
      if (!res.ok) throw new Error('Failed to fetch stock alerts')
      return res.json() as Promise<StockAlertsResponse>
    },
  })

  // ── Add-to-PO mutation ───────────────────────────────────────────────────

  const addToPOMutation = useMutation({
    mutationFn: async (itemIds: string[]) => {
      const res = await fetch('/api/inventory/stock-alerts/add-to-po', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ item_ids: itemIds }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to create POs')
      }
      return res.json() as Promise<{ po_ids: string[] }>
    },
    onSuccess: ({ po_ids }) => {
      toast.success(`Created ${po_ids.length} draft PO${po_ids.length !== 1 ? 's' : ''}`)
      setSelected(new Set())
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.stockAlerts() })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.purchaseOrders() })
      // Navigate to purchase-orders tab
      router.push('/inventory?tab=purchase-orders')
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to create POs')
    },
  })

  // ── Use-defaults mutation ─────────────────────────────────────────────────

  const useDefaultsMutation = useMutation({
    mutationFn: async () => {
      const res = await fetch('/api/inventory/items/bulk-thresholds', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ use_defaults: true }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to apply defaults')
      }
      return res.json() as Promise<{ updated: number }>
    },
    onSuccess: ({ updated }) => {
      toast.success(`Updated ${updated} threshold${updated !== 1 ? 's' : ''}`)
      setUseDefaultsDialogOpen(false)
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.stockAlerts() })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to apply defaults')
    },
  })

  // ── Selection helpers ─────────────────────────────────────────────────────

  const alerts = data?.alerts ?? []
  const allSelected = alerts.length > 0 && alerts.every((a) => selected.has(a.item_id))

  function toggleAll() {
    if (allSelected) {
      setSelected(new Set())
    } else {
      setSelected(new Set(alerts.map((a) => a.item_id)))
    }
  }

  function toggleOne(itemId: string) {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(itemId)) {
        next.delete(itemId)
      } else {
        next.add(itemId)
      }
      return next
    })
  }

  function handleSingleAddToPO(itemId: string) {
    addToPOMutation.mutate([itemId])
  }

  // ── Loading state ─────────────────────────────────────────────────────────

  if (isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 4 }).map((_, i) => (
          <Skeleton key={i} className="h-14 w-full rounded-lg" />
        ))}
      </div>
    )
  }

  const state = data?.state ?? 'all_clear'

  // ── ALL CLEAR empty state ─────────────────────────────────────────────────

  if (state === 'all_clear') {
    return (
      <>
        <div className="flex flex-col items-center justify-center py-16 gap-5">
          {/* Status label */}
          <p
            className="text-[11px] font-bold tracking-[0.08em] uppercase text-rust"
            aria-label="Status: All clear"
          >
            All Clear
          </p>

          {/* Icon circle */}
          <div
            className="flex h-14 w-14 items-center justify-center rounded-full border border-stone-brand bg-transparent"
            aria-hidden="true"
          >
            <CheckCircle2 className="h-6 w-6 text-foreground" />
          </div>

          {/* Serif headline */}
          <p className="font-serif text-[28px] italic text-foreground leading-tight">
            Inventory within healthy range
          </p>

          {/* Body */}
          <p className="text-sm text-stone-brand text-center max-w-xs leading-relaxed">
            All items above their minimum. We&apos;ll alert you the moment one drops below.
          </p>

          {/* CTA */}
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              setThresholdsMode('review-only')
              setThresholdsOpen(true)
            }}
          >
            View thresholds
          </Button>
        </div>

        <BulkThresholdsDrawer
          open={thresholdsOpen}
          onOpenChange={setThresholdsOpen}
          mode={thresholdsMode}
        />
      </>
    )
  }

  // ── ALERTS CAN'T FIRE empty state ─────────────────────────────────────────

  if (state === 'cant_fire') {
    const noMinCount = data?.items_with_no_min ?? 0

    return (
      <>
        <div className="flex flex-col items-center justify-center py-16 gap-5">
          {/* Status label */}
          <p
            className="text-[11px] font-bold tracking-[0.08em] uppercase text-rust"
            aria-label="Status: Alerts can't fire"
          >
            Alerts Can&apos;t Fire
          </p>

          {/* Icon circle — Rust tint bg */}
          <div
            className="flex h-14 w-14 items-center justify-center rounded-full bg-rust-tint"
            aria-hidden="true"
          >
            <AlertCircle className="h-6 w-6 text-rust" />
          </div>

          {/* Serif headline */}
          <p className="font-serif text-[28px] italic text-foreground leading-tight">
            No minimums set
          </p>

          {/* Body */}
          <p className="text-sm text-stone-brand text-center max-w-sm leading-relaxed">
            {noMinCount > 0
              ? `${noMinCount} item${noMinCount !== 1 ? 's' : ''} still have min = 0, so alerts will never trigger. Set thresholds in bulk.`
              : 'Some items have min = 0, so alerts will never trigger. Set thresholds in bulk.'}
          </p>

          {/* CTAs */}
          <div className="flex items-center gap-3">
            <Button
              onClick={() => {
                setThresholdsMode('manual')
                setThresholdsOpen(true)
              }}
            >
              <Settings className="mr-2 h-4 w-4" />
              Set thresholds
            </Button>
            <Button
              variant="outline"
              onClick={() => setUseDefaultsDialogOpen(true)}
            >
              Use defaults
            </Button>
          </div>
        </div>

        {/* Bulk thresholds drawer */}
        <BulkThresholdsDrawer
          open={thresholdsOpen}
          onOpenChange={setThresholdsOpen}
          mode={thresholdsMode}
        />

        {/* Use defaults confirm dialog */}
        <UseDefaultsDialog
          open={useDefaultsDialogOpen}
          onOpenChange={setUseDefaultsDialogOpen}
          itemCount={noMinCount}
          isPending={useDefaultsMutation.isPending}
          onConfirm={() => useDefaultsMutation.mutate()}
        />
      </>
    )
  }

  // ── HAS ALERTS — actionable rows ──────────────────────────────────────────

  return (
    <>
      {/* Table */}
      <div className="relative rounded-lg border border-stone-brand/20 bg-[color:var(--color-bone)] overflow-hidden shadow-[var(--shadow-card)]">
        {/* Header row */}
        <div className="flex items-center gap-3 px-4 py-2.5 border-b border-stone-brand/20 bg-[color:var(--color-bone)]">
          {/* Select-all checkbox */}
          <Checkbox
            checked={allSelected}
            onCheckedChange={toggleAll}
            aria-label="Select all alerts"
          />
          <span className="text-[11px] font-bold tracking-[0.08em] uppercase text-stone-brand flex-1">
            Item
          </span>
          <span className="hidden sm:block text-[11px] font-bold tracking-[0.08em] uppercase text-stone-brand w-24 text-center">
            Stock / Min
          </span>
          <span className="hidden md:block text-[11px] font-bold tracking-[0.08em] uppercase text-stone-brand w-40">
            Reorder
          </span>
          <span className="hidden lg:block text-[11px] font-bold tracking-[0.08em] uppercase text-stone-brand w-36">
            Supplier
          </span>
          <span className="w-24" />
        </div>

        {/* Alert rows */}
        {alerts.map((alert) => {
          const isChecked = selected.has(alert.item_id)
          const suggestedCost =
            alert.cost_per_unit_cents != null
              ? formatCurrency(alert.suggested_qty * alert.cost_per_unit_cents)
              : null

          return (
            <div
              key={alert.id}
              className="flex items-center gap-3 px-4 py-3 border-b border-stone-brand/10 last:border-0 hover:bg-stone-brand/[0.03] transition-colors"
            >
              {/* Checkbox */}
              <Checkbox
                checked={isChecked}
                onCheckedChange={() => toggleOne(alert.item_id)}
                aria-label={`Select ${alert.name}`}
              />

              {/* Item name + SKU */}
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-foreground truncate">
                  {alert.name}
                </p>
                {alert.sku && (
                  <p className="text-[12px] font-mono text-stone-brand truncate">
                    {alert.sku}
                  </p>
                )}
              </div>

              {/* Stock/min Rust pill */}
              <div className="hidden sm:flex w-24 justify-center">
                <span className="inline-flex items-center rounded-full bg-rust px-2.5 py-0.5 text-[12px] font-medium text-[color:var(--color-bone)] tabular">
                  {alert.current_stock} / {alert.min_threshold}
                </span>
              </div>

              {/* Suggested qty + cost */}
              <div className="hidden md:block w-40">
                <p className="text-sm font-medium text-foreground tabular">
                  +{alert.suggested_qty} units
                  {suggestedCost && (
                    <span className="text-stone-brand"> · {suggestedCost}</span>
                  )}
                </p>
              </div>

              {/* Supplier */}
              <div className="hidden lg:block w-36 truncate">
                <p className="text-sm text-stone-brand truncate">
                  {alert.supplier_name ?? <span className="text-stone-brand/50">—</span>}
                </p>
              </div>

              {/* Single-row Add to PO */}
              <div className="w-24 flex justify-end">
                <Button
                  variant="outline"
                  size="sm"
                  className="text-rust border-rust/40 hover:bg-rust/8 hover:text-rust text-xs h-7 px-2"
                  disabled={addToPOMutation.isPending}
