  )
}

// ── Use-defaults confirm dialog ───────────────────────────────────────────────

interface UseDefaultsDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  itemCount: number
  isPending: boolean
  onConfirm: () => void
}

function UseDefaultsDialog({
  open,
  onOpenChange,
  itemCount,
  isPending,
  onConfirm,
}: UseDefaultsDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Apply category defaults</DialogTitle>
          <DialogDescription>
            Apply category defaults to{' '}
