            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isPending}
          >
            Cancel
          </Button>
          <Button onClick={onConfirm} disabled={isPending}>
            {isPending ? 'Applying...' : 'Apply defaults'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

