'use client'

import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Skeleton } from '@/components/ui/skeleton'
import { toast } from 'sonner'
import { queryKeys } from '@/lib/query-keys'
import { formatCurrency } from '@/lib/utils'
import {
  CATEGORY_MIN_DEFAULTS,
  getCategoryDefault,
  type InventoryCategory,
} from '@/lib/inventory/category-defaults'
import type { InventoryItem } from '@/lib/supabase/types'

// ── Types ─────────────────────────────────────────────────────────────────────

export interface BulkThresholdsDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** 'review-only' hides the save button — informational view only */
  mode?: 'manual' | 'review-only'
}

interface ThresholdRow {
  item_id: string
  name: string
  sku: string | null
  category: string
  current_stock: number
  cost_per_unit_cents: number | null
  min_threshold: number
}

// ── Category badge helper ─────────────────────────────────────────────────────

const CATEGORY_COLORS: Record<string, string> = {
  ink: 'bg-[color:var(--color-rust)]/10 text-rust border-rust/30',
  needle: 'bg-stone-brand/10 text-stone-brand border-stone-brand/30',
  supply: 'bg-stone-brand/10 text-stone-brand border-stone-brand/30',
  aftercare: 'bg-stone-brand/10 text-stone-brand border-stone-brand/30',
  equipment: 'bg-stone-brand/10 text-stone-brand border-stone-brand/30',
  apparel: 'bg-stone-brand/10 text-stone-brand border-stone-brand/30',
  other: 'bg-stone-brand/10 text-stone-brand border-stone-brand/30',
}

function CategoryPill({ category }: { category: string }) {
  const classes = CATEGORY_COLORS[category] ?? CATEGORY_COLORS.other
  return (
    <span
      className={`inline-flex items-center rounded-full border px-2 py-0.5 text-[11px] font-medium capitalize ${classes}`}
    >
      {category}
    </span>
  )
}

// ── Main component ────────────────────────────────────────────────────────────

export function BulkThresholdsDrawer({
  open,
  onOpenChange,
  mode = 'manual',
}: BulkThresholdsDrawerProps) {
  const queryClient = useQueryClient()

  // Local form state: item_id → current input value
  const [thresholds, setThresholds] = useState<Record<string, number>>({})

  // ── Fetch items with min = 0 ─────────────────────────────────────────────

  const { data, isLoading } = useQuery({
    queryKey: [...queryKeys.inventory.items({ min_threshold: 0, is_active: true })],
    queryFn: async () => {
      const params = new URLSearchParams({
        min_threshold: '0',
        is_active: 'true',
        limit: '200',
      })
      const res = await fetch(`/api/inventory/items?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to load items')
      const json = await res.json() as { data: InventoryItem[] }
      return json.data
    },
    enabled: open,
  })

  // Seed form state from fetched data
  useEffect(() => {
    if (!data) return
    const initial: Record<string, number> = {}
    data.forEach((item) => {
      initial[item.id] = getCategoryDefault(item.category)
    })
    setThresholds(initial)
  }, [data])

  const items: ThresholdRow[] = (data ?? []).map((item) => ({
    item_id: item.id,
    name: item.name,
    sku: item.sku,
    category: item.category,
    current_stock: Number(item.current_stock),
    cost_per_unit_cents: item.cost_per_unit_cents,
    min_threshold: thresholds[item.id] ?? getCategoryDefault(item.category),
  }))

  // ── Apply category defaults to form state ────────────────────────────────

  function applyDefaults() {
    setThresholds((prev) => {
      const next = { ...prev }
      items.forEach((row) => {
        next[row.item_id] = getCategoryDefault(row.category)
      })
      return next
    })
  }

  function handleMinChange(itemId: string, raw: string) {
    const parsed = parseInt(raw, 10)
    if (!isNaN(parsed) && parsed >= 1) {
      setThresholds((prev) => ({ ...prev, [itemId]: parsed }))
    }
  }

  // ── Save mutation ────────────────────────────────────────────────────────

  const saveMutation = useMutation({
    mutationFn: async () => {
      const updates = items.map((row) => ({
        item_id: row.item_id,
        min_threshold: thresholds[row.item_id] ?? getCategoryDefault(row.category),
      }))

      const res = await fetch('/api/inventory/items/bulk-thresholds', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ updates }),
      })
      if (!res.ok) {
        const err = await res.json() as { error: unknown }
        throw new Error(typeof err.error === 'string' ? err.error : 'Failed to save thresholds')
      }
      return res.json() as Promise<{ updated: number }>
    },
    onSuccess: ({ updated }) => {
      toast.success(`Updated ${updated} threshold${updated !== 1 ? 's' : ''}`)
      onOpenChange(false)
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.stockAlerts() })
      void queryClient.invalidateQueries({ queryKey: queryKeys.inventory.items() })
    },
    onError: (err) => {
      toast.error(err instanceof Error ? err.message : 'Failed to save thresholds')
    },
  })

  const isReadOnly = mode === 'review-only'

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full sm:max-w-lg flex flex-col p-0">
        {/* Header */}
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-stone-brand/20">
          <div className="flex items-start justify-between gap-4">
            <div className="space-y-1">
              <SheetTitle className="text-xl font-bold text-foreground">
                Set minimum thresholds
              </SheetTitle>
              <SheetDescription className="text-sm text-stone-brand leading-relaxed">
                Items with min = 0 don&apos;t trigger alerts. Set sensible minimums per category.
              </SheetDescription>
            </div>
          </div>

          {/* Use defaults button */}
          {!isReadOnly && items.length > 0 && (
            <Button
              variant="outline"
              size="sm"
              className="self-start mt-2"
              onClick={applyDefaults}
              type="button"
            >
              Use defaults
            </Button>
          )}
        </SheetHeader>

        {/* Item list */}
        <ScrollArea className="flex-1">
          <div className="px-6 py-4">
            {isLoading ? (
              <div className="space-y-3">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Skeleton key={i} className="h-16 w-full rounded-lg" />
                ))}
              </div>
            ) : items.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 gap-3 text-center">
                <p className="font-serif text-[22px] italic text-foreground">
                  All thresholds set
                </p>
                <p className="text-sm text-stone-brand max-w-xs">
                  Every active item has a minimum threshold above zero.
                </p>
              </div>
            ) : (
              <div className="space-y-1">
                {/* Column headers */}
                <div className="grid grid-cols-[1fr_auto_auto] gap-3 px-3 py-2">
                  <span className="text-[11px] font-bold tracking-[0.08em] uppercase text-stone-brand">
                    Item
                  </span>
                  <span className="text-[11px] font-bold tracking-[0.08em] uppercase text-stone-brand w-16 text-center">
                    Stock
                  </span>
                  <span className="text-[11px] font-bold tracking-[0.08em] uppercase text-stone-brand w-24 text-center">
                    Min
                  </span>
                </div>

                {/* Rows */}
                {items.map((row) => {
                  const categoryDefault = getCategoryDefault(row.category)
                  const currentVal = thresholds[row.item_id] ?? categoryDefault

                  return (
                    <div
                      key={row.item_id}
                      className="grid grid-cols-[1fr_auto_auto] items-center gap-3 rounded-lg border border-stone-brand/10 bg-[color:var(--color-bone)] px-3 py-2.5"
                    >
                      {/* Item info */}
                      <div className="min-w-0">
                        <p className="text-sm font-medium text-foreground truncate">
                          {row.name}
                        </p>
                        <div className="flex items-center gap-2 mt-0.5">
                          {row.sku && (
                            <span className="text-[11px] font-mono text-stone-brand">
                              {row.sku}
                            </span>
                          )}
                          <CategoryPill category={row.category} />
                        </div>
                      </div>

                      {/* Current stock */}
                      <div className="w-16 text-center">
                        <span className="text-sm tabular text-stone-brand">
                          {row.current_stock}
                        </span>
                      </div>

                      {/* Min input */}
                      <div className="w-24">
                        {isReadOnly ? (
                          <span className="block text-sm tabular text-center text-foreground font-medium">
                            {currentVal}
                          </span>
                        ) : (
                          <Input
                            type="number"
                            min="1"
                            step="1"
                            value={currentVal}
                            onChange={(e) => handleMinChange(row.item_id, e.target.value)}
                            placeholder={String(categoryDefault)}
                            className="h-8 text-sm text-center tabular w-full"
                            aria-label={`Minimum threshold for ${row.name}`}
                          />
                        )}
                      </div>
                    </div>
                  )
                })}
              </div>
            )}
          </div>
        </ScrollArea>

        {/* Footer */}
        {!isReadOnly && (
          <SheetFooter className="px-6 py-4 border-t border-stone-brand/20 flex-row gap-2 justify-end">
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={saveMutation.isPending}
            >
              Cancel
            </Button>
            <Button
              onClick={() => saveMutation.mutate()}
              disabled={saveMutation.isPending || items.length === 0}
            >
              {saveMutation.isPending ? 'Saving...' : `Save ${items.length > 0 ? `${items.length} ` : ''}threshold${items.length !== 1 ? 's' : ''}`}
            </Button>
          </SheetFooter>
        )}

        {isReadOnly && (
          <SheetFooter className="px-6 py-4 border-t border-stone-brand/20 flex-row justify-end">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Close
            </Button>
          </SheetFooter>
        )}
      </SheetContent>
    </Sheet>
  )
}

// Re-export CATEGORY_MIN_DEFAULTS for external consumers (e.g., confirm dialogs)
export { CATEGORY_MIN_DEFAULTS }

